  ('topological-order', '1', 'duel', 'python', 'hard', 'Dependency ordering', 'Return a topological ordering of a DAG whose vertices are 0..n-1 and edges point from prerequisites to dependents.', 'def dependency_order(n, edges):
    outgoing = [[] for _ in range(n)]
    degree = [0] * n
    for source, target in edges:
        outgoing[source].append(target)
        degree[source] += 1
    queue = [node for node in range(n) if degree[node] == 0]
    order = []
    for node in queue:
        order.append(node)
        for target in outgoing[node]:
            degree[target] -= 1
            if degree[target] == 0:
                queue.append(target)
    return order', '15', '6', 'In-degree counts incoming edges at the target, not outgoing edges at the source. The queue must begin with prerequisite-free vertices.', 'def dependency_order(n, edges):
    outgoing = [[] for _ in range(n)]
    degree = [0] * n
    for source, target in edges:
        outgoing[source].append(target)
        degree[target] += 1
    queue = [node for node in range(n) if degree[node] == 0]
    order = []
    for node in queue:
        order.append(node)
        for target in outgoing[node]:
            degree[target] -= 1
            if degree[target] == 0:
                queue.append(target)
